## 3. `infra/modules/invoice-bucket/main.tf`

```hcl
terraform {
  required_version = "~> 1.9"
  required_providers {
    aws = { source = "hashicorp/aws", version = "~> 5.60" }
  }
}

locals {
  name = "${var.project}-${var.env}-invoices"
  tags = {
    project     = var.project
    env         = var.env
    owner       = var.owner
    "cost-center" = var.cost_center
    data_class  = "pii"
    ticket      = "TCK-60"
  }
  # dev/stage giữ ngắn ngày và không dùng dữ liệu thật
  expiration_days = var.env == "prod" ? var.retention_years * 365 : 30
}

# ---------- KMS ----------
resource "aws_kms_key" "invoices" {
  description             = "CMK ma hoa hoa don ${var.env} (PII)"
  enable_key_rotation     = true
  rotation_period_in_days = 365
  deletion_window_in_days = 30
  policy                  = data.aws_iam_policy_document.kms.json
  tags                    = local.tags
}

resource "aws_kms_alias" "invoices" {
  name          = "alias/${local.name}"
  target_key_id = aws_kms_key.invoices.key_id
}

data "aws_caller_identity" "current" {}

data "aws_iam_policy_document" "kms" {
  # quan tri khoa: chi role quan tri cua nen tang, KHONG phai ung dung
  statement {
    sid     = "KeyAdministration"
    actions = [
      "kms:Create*", "kms:Describe*", "kms:Enable*", "kms:List*", "kms:Put*",
      "kms:Update*", "kms:Revoke*", "kms:Disable*", "kms:Get*", "kms:Delete*",
      "kms:ScheduleKeyDeletion", "kms:CancelKeyDeletion", "kms:TagResource"
    ]
    resources = ["*"] # bat buoc trong key policy: pham vi da la chinh khoa nay
    principals {
      type        = "AWS"
      identifiers = ["arn:aws:iam::${data.aws_caller_identity.current.account_id}:role/platform-admin"]
    }
  }

  statement {
    sid     = "AppUseViaS3Only"
    actions = ["kms:Encrypt", "kms:Decrypt", "kms:GenerateDataKey*", "kms:DescribeKey"]
    resources = ["*"]
    principals {
      type        = "AWS"
      identifiers = [aws_iam_role.payment_service.arn]
    }
    condition {
      test     = "StringEquals"
      variable = "kms:ViaService"
      values   = ["s3.${data.aws_region.current.name}.amazonaws.com"]
    }
  }
}

data "aws_region" "current" {}

# ---------- Bucket ----------
resource "aws_s3_bucket" "invoices" {
  bucket        = local.name
  force_destroy = false
  tags          = local.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "invoices" {
  bucket                  = aws_s3_bucket.invoices.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_ownership_controls" "invoices" {
  bucket = aws_s3_bucket.invoices.id
  rule { object_ownership = "BucketOwnerEnforced" } # ACL tat hoan toan
}

resource "aws_s3_bucket_versioning" "invoices" {
  bucket = aws_s3_bucket.invoices.id
  versioning_configuration { status = "Enabled" }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "invoices" {
  bucket = aws_s3_bucket.invoices.id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.invoices.arn
    }
    bucket_key_enabled = true # giam so request KMS => giam chi phi
  }
}

resource "aws_s3_bucket_logging" "invoices" {
  bucket        = aws_s3_bucket.invoices.id
  target_bucket = var.log_bucket_id
  target_prefix = "s3-access/${local.name}/"
}

resource "aws_s3_bucket_lifecycle_configuration" "invoices" {
  bucket = aws_s3_bucket.invoices.id

  rule {
    id     = "invoices-retention"
    status = "Enabled"
    filter { prefix = "invoices/" }

    transition {
      days          = 90
      storage_class = "STANDARD_IA"
    }
    expiration { days = local.expiration_days }
    noncurrent_version_expiration { noncurrent_days = var.noncurrent_version_expiration_days }
    abort_incomplete_multipart_upload { days_after_initiation = 7 }
  }
}

resource "aws_s3_bucket_policy" "invoices" {
  bucket = aws_s3_bucket.invoices.id
  policy = data.aws_iam_policy_document.bucket.json
}

data "aws_iam_policy_document" "bucket" {
  statement {
    sid     = "DenyInsecureTransport"
    effect  = "Deny"
    actions = ["s3:*"]
    resources = [aws_s3_bucket.invoices.arn, "${aws_s3_bucket.invoices.arn}/*"]
    principals { type = "*", identifiers = ["*"] }
    condition {
      test     = "Bool"
      variable = "aws:SecureTransport"
      values   = ["false"]
    }
  }

  statement {
    sid       = "DenyWrongEncryption"
    effect    = "Deny"
    actions   = ["s3:PutObject"]
    resources = ["${aws_s3_bucket.invoices.arn}/*"]
    principals { type = "*", identifiers = ["*"] }
    condition {
      test     = "StringNotEquals"
      variable = "s3:x-amz-server-side-encryption-aws-kms-key-id"
      values   = [aws_kms_key.invoices.arn]
    }
  }

  # "Khong ai ngoai dich vu doc duoc": chan moi principal khong phai role cua payment-service
  statement {
    sid       = "DenyEveryoneExceptService"
    effect    = "Deny"
    actions   = ["s3:GetObject", "s3:PutObject", "s3:ListBucket"]
    resources = [aws_s3_bucket.invoices.arn, "${aws_s3_bucket.invoices.arn}/*"]
    principals { type = "*", identifiers = ["*"] }
    condition {
      test     = "ArnNotEquals"
      variable = "aws:PrincipalArn"
      values   = [
        aws_iam_role.payment_service.arn,
        "arn:aws:iam::${data.aws_caller_identity.current.account_id}:role/platform-admin" # de IaC quan ly cau hinh, khong doc object
      ]
    }
  }
}
```

## 4. `infra/modules/invoice-bucket/iam.tf` — quyền cho payment-service

```hcl
data "aws_iam_policy_document" "assume" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRoleWithWebIdentity"]
    principals {
      type        = "Federated"
      identifiers = [var.oidc_provider_arn]
    }
    condition {
      test     = "StringEquals"
      variable = "${var.oidc_provider_url}:sub"
      values   = ["system:serviceaccount:${var.service_namespace}:${var.service_account_name}"]
    }
    condition {
      test     = "StringEquals"
      variable = "${var.oidc_provider_url}:aud"
      values   = ["sts.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "payment_service" {
  name                 = "${local.name}-payment-service"
  assume_role_policy   = data.aws_iam_policy_document.assume.json
  max_session_duration = 3600
  tags                 = local.tags
}

data "aws_iam_policy_document" "app" {
  statement {
    sid       = "ReadWriteInvoicePrefix"
    effect    = "Allow"
    actions   = ["s3:PutObject", "s3:GetObject", "s3:GetObjectVersion"]
    resources = ["${aws_s3_bucket.invoices.arn}/invoices/*"]
    # KHONG co s3:DeleteObject, KHONG co s3:*, KHONG co resource "*"
  }

  statement {
    sid       = "ListOwnPrefixOnly"
    effect    = "Allow"
    actions   = ["s3:ListBucket"]
    resources = [aws_s3_bucket.invoices.arn]
    condition {
      test     = "StringLike"
      variable = "s3:prefix"
      values   = ["invoices/*"]
    }
  }

  statement {
    sid       = "UseCmkViaS3"
    effect    = "Allow"
    actions   = ["kms:Encrypt", "kms:Decrypt", "kms:GenerateDataKey*", "kms:DescribeKey"]
    resources = [aws_kms_key.invoices.arn]
    condition {
      test     = "StringEquals"
      variable = "kms:ViaService"
      values   = ["s3.${data.aws_region.current.name}.amazonaws.com"]
    }
  }
}

resource "aws_iam_role_policy" "app" {
  name   = "invoice-access"
  role   = aws_iam_role.payment_service.id
  policy = data.aws_iam_policy_document.app.json
}

output "bucket_name"  { value = aws_s3_bucket.invoices.id }
output "kms_key_arn"  { value = aws_kms_key.invoices.arn }
output "role_arn"     { value = aws_iam_role.payment_service.arn }
```

Backend cho payment-service: gắn annotation `eks.amazonaws.com/role-arn = <role_arn>` vào ServiceAccount `payments/payment-service`; tên bucket lấy qua biến môi trường `INVOICE_BUCKET` (config, không phải secret). Không có access key nào được tạo — không có secret trong code, biến hay state.

