## 7. Policy-as-code — `policy/s3_invoices.rego` (chạy trên plan JSON trong CI)

```rego
package terraform.s3

required_tags := {"project", "env", "owner", "cost-center"}

deny[msg] {
  r := input.resource_changes[_]
  r.type == "aws_s3_bucket"
  missing := required_tags - {k | r.change.after.tags[k]}
  count(missing) > 0
  msg := sprintf("bucket %s thieu tag bat buoc: %v", [r.address, missing])
}

deny[msg] {
  r := input.resource_changes[_]
  r.type == "aws_s3_bucket_public_access_block"
  some f in ["block_public_acls", "block_public_policy", "ignore_public_acls", "restrict_public_buckets"]
  r.change.after[f] != true
  msg := sprintf("%s: %s phai = true", [r.address, f])
}

deny[msg] {
  r := input.resource_changes[_]
  r.type == "aws_s3_bucket_server_side_encryption_configuration"
  rule := r.change.after.rule[_]
  rule.apply_server_side_encryption_by_default[_].sse_algorithm != "aws:kms"
  msg := sprintf("%s: bat buoc ma hoa aws:kms (du lieu PII)", [r.address])
}

deny[msg] {
  r := input.resource_changes[_]
  r.type == "aws_iam_role_policy"
  doc := json.unmarshal(r.change.after.policy)
  st := doc.Statement[_]
  st.Effect == "Allow"
  st.Action[_] == "*"
  msg := sprintf("%s: cam IAM action '*'", [r.address])
}

deny[msg] {
  r := input.resource_changes[_]
  r.type == "aws_iam_role_policy"
  doc := json.unmarshal(r.change.after.policy)
  st := doc.Statement[_]
  st.Effect == "Allow"
  st.Resource[_] == "*"
  not startswith(st.Sid, "UseCmk")
  msg := sprintf("%s: cam resource '*'", [r.address])
}

deny[msg] {
  r := input.resource_changes[_]
  "delete" in r.change.actions
  r.type in {"aws_s3_bucket", "aws_kms_key"}
  msg := sprintf("%s: plan co destroy tai nguyen chua du lieu — can PR rieng co backup + 2 nguoi duyet", [r.address])
}
```

## 8. Cách kiểm chứng acceptance

| Acceptance | Cách chứng minh (chạy ở dev trước) |
|---|---|
| payment-service ghi/đọc được hoá đơn | Pod dùng ServiceAccount `payments/payment-service`: `aws s3 cp test.pdf s3://<bucket>/invoices/smoke.pdf` và `aws s3 cp s3://<bucket>/invoices/smoke.pdf -` đều thành công; object có `ServerSideEncryption=aws:kms` đúng CMK |
| Không ai ngoài dịch vụ đọc được | (1) `aws s3 ls s3://<bucket>` bằng role khác → AccessDenied; (2) truy cập ẩn danh HTTPS → 403; (3) `PutObject` với SSE khác CMK → 403; (4) request HTTP (không TLS) → 403; (5) pod ở namespace khác giả mạo SA → AssumeRoleWithWebIdentity thất bại vì điều kiện `sub` |
| Mã hoá at-rest (threat-model) | `aws s3api get-bucket-encryption` trả `aws:kms` + ARN CMK; `aws kms get-key-rotation-status` trả `KeyRotationEnabled=true` |

Các bước trên là kịch bản smoke test bắt buộc trong pipeline sau apply dev/stage; **chưa được chạy trong lượt này**.

